    /// <summary>Row of design/hooks.json. Every place the mod touches Risk of Rain 2 (RoR2.dll, 2026-10 build, decompiled with ilspycmd for reference only). method = 'event' subscribes to a public RoR2 ...</summary>
    public sealed class HookRow
    {
        public string Id;
        public string Method;
        public string Target;
        public string Purpose;
        public string Reads;
        public string Side;

        public static readonly HookRow[] All = new HookRow[]
        {
            new HookRow { Id = "content_pack", Method = "event", Target = "RoR2.ContentManagement.ContentManager.collectContentPackProviders", Purpose = "register body prefabs, survivor defs, skill defs/families, entity state types and buff defs (one IContentPackProvider; loads the Deadlock cache during the loading screen)", Reads = "heroes.*, stats.*, skills.*, buffs.*", Side = "both" },
            new HookRow { Id = "language", Method = "harmony-prefix", Target = "RoR2.Language.GetLocalizedStringByToken(string)", Purpose = "answer DLR_* tokens (names, subtitles, lore, skill names/descriptions, buff names) in every language", Reads = "heroes.displayName/subtitle/lore, skills.name/description, buffs.name", Side = "client" },
            new HookRow { Id = "stats_recalc", Method = "harmony-postfix", Target = "RoR2.CharacterBody.RecalculateStats()", Purpose = "apply our buffs' move speed / attack speed / armor / regen and slow resistance (vanilla level scaling of base stats is untouched and comes from the level* fields)", Reads = "buffs.moveSpeedAdd/attackSpeedAdd/armorAdd/regenAdd/slowResist", Side = "both" },
            new HookRow { Id = "damage_mods", Method = "harmony-prefix", Target = "RoR2.HealthComponent.TakeDamage(RoR2.DamageInfo)", Purpose = "Fixation and Napalm damage amp from their owner, Bullet Dance evasion", Reads = "buffs.damageTakenFromOwnerPerStack/evasionChance", Side = "server" },
            new HookRow { Id = "model", Method = "component", Target = "DeadlockOfRain.ModelBuilder.Build (a model GameObject built per hero from the cache)", Purpose = "skeleton + one SkinnedMeshRenderer per material + legacy Animation clips from the player's Deadlock install, attached to the body's ModelLocator with CharacterModel/HurtBoxGroup/ChildLocator", Reads = "heroes.heightScale/widthScale/meshInclude, animations.*", Side = "client" },
            new HookRow { Id = "locomotion", Method = "component", Target = "DeadlockOfRain.DeadlockAnimator", Purpose = "pick idle/run/sprint/jump/land clips from CharacterMotor + InputBank each frame, layer gestures (reload/abilities) on the upper body; gun rig: hold the gun arms in aimPose, weld the gun to its hand, turn the chest so the gun points at the camera aim, recoil on shots", Reads = "animations.*", Side = "client" },
            new HookRow { Id = "audio", Method = "component", Target = "DeadlockOfRain.DeadlockAudio (winmm waveOut mixer)", Purpose = "play the hero's Deadlock sounds (decoded WAVs in the cache) at volume_master * volume_sfx, with distance falloff from the camera", Reads = "sounds.*", Side = "client" },
            new HookRow { Id = "test_mode", Method = "component", Target = "DeadlockOfRain.MeltyTest", Purpose = "Melty test.checks: while %LOCALAPPDATA%/Melty/test/deadlock-of-rain.json exists, start a run, play each hero, measure every skill's effect against skills.expect, check the gun rig, the 4 skill slots plus the starting ult equipment, level stats and scale, and append pass/fail lines to the checks file", Reads = "skills.*, stats.*, heroes.*", Side = "both" },
            new HookRow { Id = "loadout_skins", Method = "harmony-postfix", Target = "RoR2.UI.LoadoutPanelController+Row.FromSkin (public static on a private nested class)", Purpose = "give our heroes' empty skins row one 'Default' button, so the loadout panel's gamepad navigation does not index an empty row", Reads = "heroes.imageSmall/primaryColor", Side = "client" },
            new HookRow { Id = "debuff_resist", Method = "harmony-prefix", Target = "RoR2.CharacterBody.AddTimedBuffInternal(RoR2.BuffDef,float,float) (private)", Purpose = "shorten timed debuffs on a hero with debuffResist (Abrams' Infernal Resilience)", Reads = "heroes.debuffResist", Side = "server" },
            new HookRow { Id = "heal_back", Method = "event", Target = "RoR2.GlobalEventManager.onServerDamageDealt", Purpose = "a hero with damageHealBack heals back that fraction of each hit taken over damageHealBackTime (Infernal Resilience)", Reads = "heroes.damageHealBack/damageHealBackTime", Side = "server" },
            new HookRow { Id = "stack_triggers", Method = "component", Target = "DeadlockOfRain.Buffs.Stack (called from our guns and projectiles)", Purpose = "add stacking debuffs (crits add critStacks) and fire their trigger at triggerStacks: Fixation burst, Static discharge, Afterburn ignition; the flash and arcs reach every player through the relay effect", Reads = "buffs.critStacks/trigger*/withBuff", Side = "server" },
            new HookRow { Id = "mired_urn", Method = "component", Target = "RoR2's SiphonNearbyBodyAttachment (Mired Urn) spawned on Abrams for Siphon Life", Purpose = "tether up to chainCount enemies within radius, drain damagePct per second, heal Abrams for the damage", Reads = "skills(abrams_siphon).*", Side = "server" },
            new HookRow { Id = "warbanner_ward", Method = "component", Target = "RoR2's WarbannerWard (BuffWard) placed for Thunderhead", Purpose = "give allies inside Seven's storm the vanilla Warbanner buff (+30% attack and move speed)", Reads = "skills(seven_thunderhead).radius/duration/extra", Side = "server" },
            new HookRow { Id = "kill_heal", Method = "event", Target = "RoR2.GlobalEventManager.onCharacterDeathGlobal", Purpose = "Concussive Combustion: each kill by the blast heals Infernus healFraction of his max health", Reads = "skills(infernus_combustion).healFraction", Side = "server" },
            new HookRow { Id = "equipment_defs", Method = "event", Target = "RoR2.ContentManagement.ContentManager.collectContentPackProviders (ContentPack.equipmentDefs)", Purpose = "register one EquipmentDef per equipment row (cooldown, drop rules, icon, a small hero figure as the pickup model); RoR2 puts canDrop equipment into the chest pools itself", Reads = "equipment.*, skills(slot=equipment).cooldown/icon/name/description", Side = "both" },
            new HookRow { Id = "equipment_fire", Method = "harmony-prefix", Target = "RoR2.EquipmentSlot.PerformEquipmentAction(RoR2.EquipmentDef) (private)", Purpose = "answer true for our equipment so RoR2 spends the charge and starts the 120 s cooldown; starts the ult state at once when this side has authority over the body (the host's own body, AI bodies, Bottled Chaos)", Reads = "equipment.skill, skills.kind", Side = "server" },
            new HookRow { Id = "equipment_fire_client", Method = "harmony-postfix", Target = "RoR2.EquipmentSlot.RpcOnClientEquipmentActivationRecieved() (private ClientRpc)", Purpose = "on a remote client that owns the body, start the ult state there (states run where the body has authority)", Reads = "equipment.skill, skills.kind", Side = "client" },
            new HookRow { Id = "starting_equipment", Method = "event", Target = "RoR2.CharacterBody.onBodyStartGlobal", Purpose = "a Deadlock hero's first body of the run gets their own ult equipment (once per player; swap it away and it stays gone)", Reads = "equipment.hero", Side = "server" },
            new HookRow { Id = "torment_pulse", Method = "component", Target = "DeadlockOfRain.PulseAura on the body (Torment Pulse)", Purpose = "Torment Pulse's pulses: rings and sound on every machine, damage and Afterburn build-up on the server", Reads = "skills(kind=aura_pulse).*", Side = "both" },
            new HookRow { Id = "voice_select", Method = "event", Target = "RoR2.CharacterBody.onBodyStartGlobal", Purpose = "voice: the local player's hero says a select line once per stage (run start and every new world), and its skill activations are listened to", Reads = "voice.*", Side = "client" },
            new HookRow { Id = "voice_skill", Method = "event", Target = "RoR2.CharacterBody.onSkillActivatedAuthority", Purpose = "voice: a skill of the local player's body starts; its row's hero says the skill's line (chance and gap from the sheet)", Reads = "voice.*, skills.id", Side = "client" },
            new HookRow { Id = "voice_unselect", Method = "event", Target = "RoR2.TeleporterInteraction.onTeleporterFinishGlobal", Purpose = "voice: the teleporter finishes (leftover gold turns into experience, the player is about to leave); the local hero says an unselect line", Reads = "voice.*", Side = "client" },
            new HookRow { Id = "voice_multikill", Method = "event", Target = "RoR2.GlobalEventManager.onCharacterDeathGlobal", Purpose = "voice: kills by the local player's hero within 1.5 s of each other; the highest killstreak line reached plays once per burst", Reads = "voice.kills", Side = "client" },
            new HookRow { Id = "gun_hits", Method = "event", Target = "RoR2.GlobalEventManager.onServerDamageDealt", Purpose = "a hero gun's bullet (damage source Primary, dealt by the hero) stacks the gun's buff and fires Power Surge's arcs, for the host's hero and a joined player's alike (their bullets are resolved on their own PC)", Reads = "skills.buff/vfx/interval, buffs.*", Side = "server" },
            new HookRow { Id = "relay_effect", Method = "event", Target = "RoR2.ContentManagement.ContentPack.effectDefs + RoR2.EffectManager.SpawnEffect(transmit)", Purpose = "co-op: one effect of ours whose EffectData says which sound or visual to play; RoR2 sends it to every player once (server-only code, gun shots and reloads of a joined player)", Reads = "effects.id, sounds.skill", Side = "both" },
            new HookRow { Id = "mod_list", Method = "event", Target = "RoR2.NetworkModCompatibilityHelper.networkModList", Purpose = "co-op: add melty.deadlockofrain;<version>, so only players with the same version can join each other (RoR2's own mod-mismatch kick)", Reads = "none", Side = "both" },
            new HookRow { Id = "melty_join", Method = "component", Target = "RoR2.PlatformSystems.lobbyManager (polled) + console connect / steam_lobby_join", Purpose = "Melty's play-together contract: the host's own Steam lobby goes in %LOCALAPPDATA%/DeadlockOfRain/melty.log as its join address; a join= line in melty.properties joins that game from the title screen", Reads = "none", Side = "client" },
            new HookRow { Id = "coop_test_auth", Method = "harmony-postfix", Target = "RoR2.Networking.NetworkManagerSystemSteam.PlatformAuth (joiner) + RoR2.SteamworksServerManager.OnAuthDataReceivedFromClient/OnAuthChange prefixes (host); private, patched by name", Purpose = "co-op test only (two copies on one PC share one Steam account): the joining copy presents another id and the host skips the Steam ticket check. Never patched outside the test", Reads = "none", Side = "both" },
        };
    }

